from flask import Flask, request, redirect, jsonify
import html
import checks, ui, db

app = Flask(__name__)

# ---- SQLite: users are saved in database.db ----
db.run("CREATE TABLE IF NOT EXISTS users (username TEXT PRIMARY KEY, password TEXT NOT NULL)")
db.run("INSERT OR IGNORE INTO users (username, password) VALUES ('rajeev', 'ilp123')")
users = {r["username"]: r["password"] for r in db.rows("SELECT username, password FROM users")}   # username -> password


def save():
    db.many([("INSERT OR REPLACE INTO users (username, password) VALUES (?, ?)", (u, p)) for u, p in users.items()])
state = {"msg": "", "ok": False, "user": None, "added": False}


def message():
    if not state["msg"]:
        return ""
    return '<div class="msg %s">%s</div>' % ("ok" if state["ok"] else "bad", state["msg"])


@app.route("/")
def home():
    S = checks.load_all()
    if S[5]["status"] == "done" and not state["added"]:
        S[5]["f"](users)
        state["added"] = True
        save()

    if state["user"]:
        w = ui.part(S[8], html.escape(state["user"]))
        body = '<div class="card">' + w + '<p>You are logged in.</p><a href="/logout"><button class="alt">Logout</button></a></div>'
    else:
        login = ('<form method="post" action="/login">' + ui.part(S[2]) + ui.part(S[3]) + ui.part(S[4]) + "</form>")
        if S[9]["status"] == "done":
            reg = ('<form method="post" action="/register"><input name="username" placeholder="New username">'
                   '<input name="password" type="password" placeholder="New password"><button class="amber">Sign up</button></form>')
        else:
            reg = ui.box(S[9])
        body = ('<div class="card">' + ui.part(S[1]) + message() + login + "</div>"
                + '<div class="card"><h2>New here? Sign up</h2>' + reg + (ui.box(S[10]) if S[10]["status"] != "done" else
                  '<p style="color:#6b7480">Password must have 6 or more characters.</p>') + "</div>")
    my = ui.box(S[5]) if S[5]["status"] != "done" else ""
    saved = '<div class="card"><h2>Saved users</h2><p>%s</p>%s</div>' % (", ".join(html.escape(u) for u in users), my)
    return ui.page("Student Login", S, body + saved)


@app.route("/login", methods=["POST"])
def login():
    u = request.form.get("username", "").strip()
    p = request.form.get("password", "")
    S = checks.load_all()
    state["ok"] = False
    if S[6]["status"] != "done":
        state["msg"] = "Step 6 is not done yet, so we cannot check the username."
    elif not S[6]["f"](users, u):
        state["msg"] = "User not found ❌  (try rajeev / ilp123)"
    elif S[7]["status"] != "done":
        state["msg"] = "User found ✅, but step 7 is not done yet, so we cannot check the password."
    elif not S[7]["f"](users, u, p):
        state["msg"] = "Wrong password ❌"
    else:
        state["user"], state["msg"] = u, ""
    return redirect("/")


@app.route("/register", methods=["POST"])
def register():
    u = request.form.get("username", "").strip()
    p = request.form.get("password", "")
    S = checks.load_all()
    state["ok"] = False
    if not u:
        state["msg"] = "Type a username to register."
    elif S[10]["status"] == "done" and not S[10]["f"](p):
        state["msg"] = "Password too short ❌  It needs 6 or more characters."
    elif S[9]["status"] == "done":
        S[9]["f"](users, u, p)
        save()
        state["ok"], state["msg"] = True, "Account created for %s ✅  Now log in." % html.escape(u)
    return redirect("/")


# ==============================================================
#  API — ready-made. Call it with curl: commands/08_api_crud.txt
# ==============================================================
def body():
    return request.get_json(silent=True) or request.form


@app.get("/api/users")
def api_users():                                  # SELECT username FROM users
    return jsonify(sorted(users))


@app.post("/api/signup")
def api_signup():                                 # INSERT INTO users ...
    b = body()
    u, p = str(b.get("username", "")).strip(), str(b.get("password", ""))
    if not u or not p:
        return jsonify(error="username and password are required"), 400
    if u in users:
        return jsonify(error="username already taken"), 409
    if len(p) < 6:
        return jsonify(error="password needs 6 or more characters"), 400
    users[u] = p
    save()
    return jsonify(message="account created", username=u), 201


@app.post("/api/login")
def api_login():                                  # SELECT password FROM users WHERE username = ...
    b = body()
    u, p = str(b.get("username", "")).strip(), str(b.get("password", ""))
    if users.get(u) != p:
        return jsonify(error="wrong username or password"), 401
    return jsonify(message="Welcome, %s!" % u)


@app.route("/logout")
def logout():
    state["user"], state["msg"] = None, ""
    return redirect("/")


if __name__ == "__main__":
    print("\n  👉 Open http://localhost:5001 in your browser.  (Stop: Ctrl + C)\n")
    app.run(port=5001)
